class RenderBoundary extends Component<{children:ReactNode},{failed:boolean}> {
  state={failed:false}
  static getDerivedStateFromError(){return {failed:true}}
  render(){return this.state.failed?<div className="empty-state"><Box size={40}/><h2>3D is unavailable on this device</h2><p>The schematic and terminal views remain available. WebGL is required for the physical workbench.</p></div>:this.props.children}
}

